/**
 * Phase 3: Registry Loader & Manager
 *
 * Loads commands-registry.json at startup and provides an on-demand
 * drift check against Core's live catalog.
 *
 * The committed registry (generated by Phase 2's
 * scripts/generate-command-registry.js) is an INTERNAL artifact
 * describing Core's Discord-adapter catalog — it is NOT the bot's
 * public command reference (buildDuneCommand() registers bot-side
 * commands, like the whole `core` group and the fanned-out `logs`
 * subcommands, that Core's catalog knows nothing about). The public
 * GET /api/commands contract is served by commands.js's curated
 * getCommandRegistry() — see issue #196 for the divergence this
 * distinction resolves.
 *
 * Multi-tenancy (issue #192): each guild talks to its OWN Core, so a
 * catalog fetched with one guild's credentials must never be written
 * into shared process state. fetchCoreCatalogForGuild() is therefore
 * side-effect-free: it fetches, transforms, validates, and RETURNS the
 * invoking guild's catalog for comparison — the shared cache is only
 * ever populated from the committed artifact at startup.
 *
 * Tracked by yacketrj/arrakis-control-panel#181 (Phase 3) and #190
 * (2026-08-20 review remediation).
 */

import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { logInfo, logError } from "./logger.js";
import { transformCatalogToRegistry, applyCommandOverrides, countSubcommands } from "./catalogTransform.js";

const __dirname = dirname(fileURLToPath(import.meta.url));
const repoRoot = join(__dirname, "..");

// In-memory registry cache — written ONLY by loadRegistryAtStartup()
// (committed artifact); never by a per-guild fetch (issue #192).
let cachedRegistry = null;
let registryLoadTime = null;

/**
 * Validate registry structure before use
 * SEC-4 FIX: Validate command names against Discord constraints.
 * Throws if registry is malformed.
 *
 * Names are validated AS-IS (issue #206/K10): Discord requires
 * lowercase names, and lowercasing before the lowercase-only regex made
 * the check unable to reject the very names it exists to reject.
 */
export function validateRegistry(registry) {
  if (!registry || typeof registry !== "object") {
    throw new Error("Registry must be an object");
  }
  if (!Array.isArray(registry.groups)) {
    throw new Error("Registry.groups must be an array");
  }
  if (typeof registry.version !== "number") {
    throw new Error("Registry.version must be a number");
  }

  // SEC-3 FIX: Validate registry size to prevent DoS
  if (registry.groups.length > 25) {
    throw new Error("Registry cannot have more than 25 command groups (Discord limit)");
  }

  for (const group of registry.groups) {
    if (!group.name || typeof group.name !== "string") {
      throw new Error(`Group missing or invalid name: ${JSON.stringify(group)}`);
    }

    if (!/^[a-z0-9_-]{1,32}$/.test(group.name)) {
      throw new Error(`Group name "${group.name}" violates Discord naming constraints (a-z, 0-9, _, -, 1-32 chars)`);
    }

    if (!Array.isArray(group.subcommands)) {
      throw new Error(`Group "${group.name}" subcommands must be an array`);
    }

    if (group.subcommands.length > 25) {
      throw new Error(`Group "${group.name}" cannot have more than 25 subcommands (Discord limit)`);
    }

    for (const sc of group.subcommands) {
      if (!sc.name || typeof sc.name !== "string") {
        throw new Error(`Subcommand in group "${group.name}" missing or invalid name`);
      }

      if (!/^[a-z0-9_-]{1,32}$/.test(sc.name)) {
        throw new Error(`Subcommand "${sc.name}" violates Discord naming constraints`);
      }

      if (typeof sc.description !== "string") {
        throw new Error(`Subcommand "${sc.name}" description must be a string`);
      }

      // SEC-5 FIX: Validate params if present
      if (sc.params && Array.isArray(sc.params)) {
        for (const param of sc.params) {
          if (!param.name || typeof param.name !== "string") {
            throw new Error(`Parameter in subcommand "${sc.name}" missing name`);
          }
          if (!/^[a-z0-9_]{1,32}$/.test(param.name)) {
            throw new Error(`Parameter name "${param.name}" violates Discord constraints`);
          }
        }
      }
    }
  }

  return true;
}

/**
 * Load src/commandOverrides.json for use during a drift check.
 * Best-effort: an operator-editable file going missing/malformed
 * should not break /dune admin sync-commands entirely — falls back to
 * no overrides (Core's raw names/tiers) and logs why, rather than
 * throwing and discarding an otherwise-valid fetch.
 */
function loadOverridesForRefresh() {
  try {
    const overridesPath = join(repoRoot, "src", "commandOverrides.json");
    return JSON.parse(readFileSync(overridesPath, "utf8"));
  } catch (error) {
    logInfo("registry.overrides_load_failed_during_refresh", {
      note: "Proceeding without bot-side overrides (exclude/rename/retier) for this drift check.",
      error: error.message
    });
    return {};
  }
}

/**
 * Load commands-registry.json from disk at startup.
 * Validates registry structure before caching.
 * This is a MANDATORY startup step — the bot will not start without a
 * valid registry (see index.js).
 */
export function loadRegistryAtStartup() {
  try {
    const registryPath = join(repoRoot, "src", "commands-registry.json");
    const registryJson = readFileSync(registryPath, "utf8");
    const registry = JSON.parse(registryJson);

    validateRegistry(registry);

    cachedRegistry = registry;
    registryLoadTime = new Date();

    logInfo("registry.loaded_at_startup", {
      groups: cachedRegistry.groups?.length || 0,
      commands: countSubcommands(cachedRegistry),
      version: cachedRegistry.version,
      timestamp: registryLoadTime.toISOString()
    });

    return cachedRegistry;
  } catch (error) {
    logError("registry.load_failed", error);
    throw new Error(`Failed to load command registry: ${error.message}`);
  }
}

/**
 * Get the currently cached registry
 * Throws if registry hasn't been loaded yet
 */
export function getRegistryFromCache() {
  if (!cachedRegistry) {
    const err = new Error("Registry not loaded. Call loadRegistryAtStartup() first.");
    logError("registry.cache_miss", err);
    throw err;
  }
  return cachedRegistry;
}

/**
 * Fetch the invoking guild's Core catalog, transform it to the bot's
 * flat registry shape, apply bot-side overrides, and validate it.
 *
 * SIDE-EFFECT-FREE by design (issue #192): the result is RETURNED for
 * drift comparison, never cached. In multi-tenant mode every guild
 * talks to its own Core with its own credentials — writing one
 * tenant's catalog into shared process state let any tenant's admin
 * (or a malicious tenant's Core) overwrite what every other tenant and
 * the public API saw. Nothing re-registers Discord commands from a
 * fetched catalog either (registration happens at deploy from code),
 * so caching it bought nothing and risked everything.
 *
 * Preserves the adapter's HTTP status on the thrown error (`.status`)
 * so callers can classify failures without substring-matching message
 * text (issue #199).
 */
export async function fetchCoreCatalogForGuild(adapterClient, actor, guildId) {
  try {
    const rawResponse = await adapterClient.discordCatalog(actor, guildId);
    const transformed = transformCatalogToRegistry(rawResponse);
    const registry = applyCommandOverrides(transformed, loadOverridesForRefresh());
    validateRegistry(registry);
    return registry;
  } catch (error) {
    logError("registry.drift_check_failed", error, { status: error?.status });
    const wrapped = new Error(`Failed to fetch Core catalog: ${error.message}`);
    wrapped.status = error?.status;
    throw wrapped;
  }
}

/**
 * Compare two registries by their `${group}:${subcommand}` keys.
 * Returns what the fetched catalog adds/removes relative to the
 * committed artifact — the payload of a sync-commands drift check.
 */
export function diffRegistries(current, fetched) {
  const keys = (registry) => {
    const set = new Set();
    for (const group of registry?.groups || []) {
      for (const sc of group.subcommands || []) {
        set.add(`${group.name}:${sc.name}`);
      }
    }
    return set;
  };

  const currentKeys = keys(current);
  const fetchedKeys = keys(fetched);

  return {
    added: [...fetchedKeys].filter((k) => !currentKeys.has(k)).sort(),
    removed: [...currentKeys].filter((k) => !fetchedKeys.has(k)).sort(),
    inSync: currentKeys.size === fetchedKeys.size && [...currentKeys].every((k) => fetchedKeys.has(k))
  };
}

/**
 * Get registry metadata (load time, version, command count)
 */
export function getRegistryMetadata() {
  return {
    loadTime: registryLoadTime,
    version: cachedRegistry?.version,
    groups: cachedRegistry?.groups?.length || 0,
    commandCount: countSubcommands(cachedRegistry)
  };
}

/**
 * Test-only: reset all module-level state.
 * Not used by production code paths — exists solely so
 * test/registryLoader.test.js can start each test from a clean slate
 * instead of leaking cache state across tests in the same process.
 */
export function __resetForTests() {
  cachedRegistry = null;
  registryLoadTime = null;
}
